import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BGlkWkwp.js";const g=JSON.parse('{"title":"Shell","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/shell.md","filePath":"workbench/shell.md"}'),h={name:"workbench/shell.md"};function s(r,e,c,i,n,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to &quot;Shell&quot;">​</a></h1><p>Shell is the frame of a drawing application: the bar at the top, a region on each side, the stage in the middle, the toolbar over the bottom of the stage and a dock under it, with the keyboard shortcuts of the whole screen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it once, as the whole screen of a drawing application. Each region is a snippet and any may be absent: the application passes a <a href="./../components/topbar">Topbar</a> in <code>top</code>, a <a href="./../components/panel">Panel</a> in <code>left</code> and in <code>right</code>, a <a href="./../components/drawbar">Drawbar</a> in <code>bottom</code>, a Panel with <code>side=&quot;fill&quot;</code> in <code>dock</code>, and whatever it draws on in <code>stage</code>. The shell places them and moves the side regions as the window narrows; it knows nothing of what they hold. A special mode of the application, such as a print preview or an older version, is a change of what the application passes in <code>stage</code> and the side regions, not a mode of the shell.</p><p>Use <code>overlay</code> when the shell lies over a drawing surface that the page owns, such as a map that is not passed in <code>stage</code>: the shell lets the pointer through to it everywhere but its regions.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>leftOpen</code></td><td><code>true</code></td><td>Whether the left region shows (bindable)</td></tr><tr><td><code>rightOpen</code></td><td><code>false</code></td><td>Whether the right region shows (bindable)</td></tr><tr><td><code>dockHeight</code></td><td></td><td>The dock&#39;s height in px (bindable); 38.2% without it</td></tr><tr><td><code>shortcuts</code></td><td><code>[]</code></td><td>The keyboard shortcuts, <code>Shortcut[]</code></td></tr><tr><td><code>shortcutsOpen</code></td><td><code>false</code></td><td>Whether the list of shortcuts is open (bindable)</td></tr><tr><td><code>overlay</code></td><td><code>false</code></td><td>Lets the pointer through, except on its regions</td></tr><tr><td><code>leftLabel</code></td><td></td><td>The name of the left region&#39;s sheet</td></tr><tr><td><code>rightLabel</code></td><td></td><td>The name of the right region&#39;s sheet</td></tr><tr><td><code>onlayout</code></td><td></td><td>Called with <code>{ width, leftMode, rightMode }</code> when they change</td></tr><tr><td><code>onescape</code></td><td></td><td>Called with Escape when no pane is left to close</td></tr></tbody></table><p><code>width</code> is <code>wide</code>, <code>mid</code> or <code>narrow</code>, and each mode is <code>beside</code>, <code>floating</code> or <code>sheet</code>. <code>onescape</code> returns <code>false</code> to leave the key to the browser.</p><p>A <code>Shortcut</code> is <code>{ key, label, run, when?, group? }</code>. <code>key</code> is written without regard to the platform: modifiers joined with <code>+</code>, then one key, such as <code>mod+z</code>, <code>shift+mod+z</code>, <code>alt+l</code> or <code>?</code>; <code>mod</code> is ⌘ on a Mac and Ctrl elsewhere, and named keys are <code>escape</code>, <code>enter</code>, <code>tab</code>, <code>space</code>, <code>backspace</code>, <code>delete</code>, <code>plus</code>, <code>minus</code>, the arrows <code>up</code>, <code>down</code>, <code>left</code> and <code>right</code>, <code>home</code>, <code>end</code>, <code>pageup</code>, <code>pagedown</code> and <code>f1</code> to <code>f12</code>. <code>run</code> is called with the key event; when it returns <code>false</code> the key goes on to the next shortcut with the same key, and to the browser. <code>when</code> says whether the shortcut acts now, and <code>group</code> is the heading it is listed under. <code>formatShortcut(key)</code> writes a key as the platform does (⇧⌘Z on a Mac, Ctrl+Shift+Z elsewhere), for a tooltip or a menu.</p><h2 id="snippets" tabindex="-1">Snippets <a class="header-anchor" href="#snippets" aria-label="Permalink to &quot;Snippets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Snippet</th><th>Holds</th></tr></thead><tbody><tr><td><code>top</code></td><td>The bar at the top, a Topbar</td></tr><tr><td><code>left</code></td><td>The left region, a Panel</td></tr><tr><td><code>right</code></td><td>The right region, a Panel</td></tr><tr><td><code>stage</code></td><td>The drawing surface; it fills the rest</td></tr><tr><td><code>bottom</code></td><td>The toolbar over the bottom of the stage, a Drawbar</td></tr><tr><td><code>dock</code></td><td>The area under the stage, a Panel with <code>side=&quot;fill&quot;</code></td></tr><tr><td><code>veil</code></td><td>While given, it covers the stage in a <a href="./../components/veil">Veil</a></td></tr></tbody></table><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The side regions follow the three widths of the layout, measured in rem so that a larger text size counts as a narrower window. The shell measures its own element, not the window, and it is the size container <code>app</code> of everything inside it, so the components in its regions follow the shell&#39;s width too, with or without the base CSS. When the browser has no <code>ResizeObserver</code>, it measures the window.</p><ul><li>From 64rem, the side regions stand beside the stage, as tall as the space under the bar, with a strong line towards the stage.</li><li>From 48 to 64rem, they float over the stage in a <a href="./../components/floating">Floating</a>, gap-md from its edges and no wider than half the stage, over a scrim that closes them when pressed.</li><li>Below 48rem, each is a <a href="./../components/sheet">Sheet</a> from the bottom of the stage, and the toolbar rises to stay above the sheets.</li></ul><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The top bar keeps its height. Under it, the side regions and a column of the stage and the dock fill the rest; the stage is the positioned frame of everything that lies over the drawing: the toolbar, the floating panes, the sheets and the veil. The dock is under the stage with a strong line along its top, at least a toolbar high, and it leaves the stage a toolbar&#39;s height at least. Its top edge is a grip without a look: a drag changes <code>dockHeight</code>, the arrow keys move it by 32px, and the value that is kept is the height after those limits. The grip&#39;s name is the <code>dockHeight</code> message and the scrim&#39;s the <code>closePanes</code> message.</p><p>The shortcuts are attached to the document while the shell is mounted. The first shortcut whose key matches and whose <code>when</code> holds runs. The help key (?, the Help key or F1) opens a <a href="./shortcuts-modal">ShortcutsModal</a> that lists them, unless a shortcut takes the key first. Escape closes the floating pane or the sheet that was opened last and returns the focus to where it was when that pane opened; when none is open, it goes to <code>onescape</code>. Beside the stage, the panels stay open on Escape. Keys typed into a field, keys an input method is composing, keys already handled (<code>defaultPrevented</code>) and keys pressed while a modal dialog or a popover is open belong to them, not to the shell.</p><p>With <code>overlay</code>, the root and the stage have <code>pointer-events: none</code>, and the bar, the side regions, the toolbar, the dock, the scrim, the floating panes, the sheets, the veil and the list of shortcuts have <code>pointer-events: auto</code>. What the application passes in <code>stage</code> lets the pointer through too.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/shell/" title="Shell" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/shell/" target="_blank" rel="noopener">Shell</a></figcaption></figure>',20)])])}const u=t(h,[["render",s]]);export{g as __pageData,u as default};
